import sys
import json

def main():
    active_state = 'A'

    # 1. Check command line arguments first
    if len(sys.argv) > 1:
        try:
            input_data = json.loads(sys.argv[1])
            active_state = input_data.get('active_state', 'A').upper()
        except Exception:
            pass
    else:
        # 2. Check stdin if no command line argument is provided
        try:
            stdin_data = sys.stdin.read().strip()
            if stdin_data:
                input_data = json.loads(stdin_data)
                active_state = input_data.get('active_state', 'A').upper()
        except Exception:
            pass

    if active_state not in ['A', 'B']:
        active_state = 'A'

    print(f"=== B1F Gate Circuit Solver (Active State: {active_state}) ===")

    # Gate definitions
    gates = {
        'B1F-Center': {'coords': '(13, 22)-(13, 23)', 'A': 'CLOSED', 'B': 'OPEN'},
        'B1F-East': {'coords': '(26, 17)-(27, 17)', 'A': 'CLOSED', 'B': 'OPEN'},
        'B1F-West': {'coords': '(1, 17)', 'A': 'OPEN', 'B': 'CLOSED'},
        'Wall/Blockage': {'coords': '(9, 14)', 'A': 'CLOSED', 'B': 'CLOSED'}
    }

    for name, info in gates.items():
        state = info[active_state]
        print(f"- Gate {name} at {info['coords']} is {state}")

    print("\nPassable Map Connectivity Details:")
    if active_state == 'B':
        print("1. Center Gate (13, 22) is OPEN. East Gate (26, 17) is OPEN. West Gate (1, 17) is CLOSED.")
        print("2. Path to Mewtwo Statue (18, 25): Column 12 to Row 22, cross Center Gate to Column 14 Row 22, east to Column 18, and south.")
    else:
        print("1. Center Gate (13, 22) is CLOSED. East Gate (26, 17) is CLOSED. West Gate (1, 17) is OPEN.")
        print("2. Path to Secret Key: Row 18 is open. Walk left to Column 1, go north through open West Gate (1, 17) directly to Northwest Room!")

if __name__ == '__main__':
    main()
